-- Generated from the changelog of the repo, do not edit.
local _, ns = ...
ns.Data = ns.Data or {}
ns.Data.Changelog = {
  v = 1,
  versions = {
    {
      version = "0.7.2",
      highlights = {
      },
      fixed = {
        { de = "Schlafsack: Die Leiste startet auch im Sack eines anderen Spielers sofort beim Hinlegen.", en = "Sleeping bag: the bar also starts at once in another player's bag.", go = "settings:sleepbag.main" },
        { de = "Schlafsack: Legst du dich nach dem Aufstehen wieder in einen Sack, startet die Leiste sofort, Gasthäuser und Städte lösen sie nicht aus.", en = "Sleeping bag: lying down again in a bag starts the bar at once, inns and cities do not trigger it.", go = "settings:sleepbag.main" },
      },
    },
    {
      version = "0.7.1",
      date = "2026-11-12",
      highlights = {
      },
      fixed = {
        { de = "Tooltips: Tooltips liegen im Einrichtungsfenster und anderen Fenstern über dem Fensterrahmen.", en = "Tooltips: tooltips sit above the frame in the setup window and other windows." },
      },
    },
    {
      version = "0.7.0",
      date = "2026-11-11",
      highlights = {
        { head = { de = "Chat-Name", en = "Chat name" }, text = { de = "Auf Wunsch steht dein Name vor deinen Nachrichten, mit Klammern, Profil und Klassenfarbe.", en = "Your name can stand in front of your messages, with brackets, a profile and class color." }, go = "settings:chatname.main" },
        { head = { de = "Angeln mit Hilfe und Journal", en = "Fishing with help and a journal" }, text = { de = "Eine Taste wirft aus und holt ein, das Journal zeigt jeden Fang und jeden Angelplatz mit Chancen.", en = "One key casts and reels in, and the journal shows every catch and fishing place with its chances." }, go = "settings:fishing.cast" },
        { head = { de = "Instanzen als Kartenraster", en = "Instances as a card grid" }, text = { de = "Jede Instanz hat ihr Ladebild, dazu Beute nach Boss, Quest-Tafel mit Text und Dungeonkarten.", en = "Every instance has its loading screen, plus loot by boss, quest panel with text and dungeon maps." }, go = "instances" },
        { head = { de = "Einstellungen mit Suche", en = "Settings with search" }, text = { de = "43 Reiter in acht Gruppen, Suche nach einzelnen Einstellungen und ein neu gebauter Einrichtungsassistent.", en = "43 tabs in eight groups, a search for single settings and a rebuilt setup wizard." }, go = "settings" },
      },
      added = {
        { de = "Forever Chat: Zeilen lassen sich kopieren, weiterleiten und beantworten, Links sind klickbar.", en = "Forever Chat: lines can be copied, forwarded and replied to, and links are clickable.", go = "settings:foreverchat" },
        { de = "Chat-Name: Auf Wunsch steht dein Name vor deinen Nachrichten, mit Klammern, Profil und Klassenfarbe.", en = "Chat name: optionally put your own name in front of your messages, with brackets, profile and class color.", go = "settings:chatname.main" },
        { de = "Angelhilfe: Eine Taste wirft aus und holt ein, auf Wunsch mit Autoplündern und lauterem Ton.", en = "Fishing helper: one key casts and reels in, optionally with auto loot and louder sound.", go = "settings:fishing.cast" },
        { de = "Fangjournal: \"Meine Fänge\" zeigt jeden Fisch mit Fängen, Fundorten und Rezepten.", en = "Catch journal: \"My catches\" shows every fish with catches, locations and recipes.", go = "settings:fishing.journal" },
        { de = "Angelplätze: Ein Fenster nennt Gebiete, Mindest-Skill und Fangchance pro Wurf.", en = "Fishing places: a window lists areas, minimum skill and catch chance per cast.", go = "settings:fishing" },
        { de = "Instanzen: Das Raster zeigt Ladebilder, startet nach Stufe sortiert und hat eine gemeinsame Fraktionswahl.", en = "Instances: the grid shows loading screens, starts sorted by level and shares one faction choice.", go = "instances" },
        { de = "Instanzen: Der Reiter Items zeigt Beute nach Boss mit Droprate, Quests zeigen Text und Startort.", en = "Instances: the Items tab lists loot by boss with drop rate, and quests show text and where they start.", go = "instances" },
        { de = "Dungeonkarten: Zoom, Eingang und Legende, zwei weitere Instanzen haben jetzt eine Karte.", en = "Dungeon maps: zoom, entrance and a legend, and two more instances now have a map.", go = "instances" },
        { de = "Sammelpunkte: Truhen, Muscheln, Fischschwärme und Wrackteile haben einen eigenen Schalter.", en = "Gathering spots: chests, clams, fish schools and wreckage have a switch of their own.", go = "settings:gathering.pins" },
        { de = "Händler: Eine neue Seite findet Händler mit Suche, Filtern und Wegpunkt.", en = "Vendors: a new page finds vendors with search, filters and waypoint.", go = "vendors" },
        { de = "Suche: Das Suchfeld im Fensterkopf springt zu Menüpunkten, Reitern und einzelnen Einstellungen.", en = "Search: the field in the window header jumps to menu pages, tabs and single settings.", go = "search" },
        { de = "Einrichtung: Im Schritt \"Menü-Bereiche\" blendest du Bereiche und Seiten mit ihrem Symbol ein und aus.", en = "Setup: in the step \"Menu areas\" you show and hide areas and pages, each with its icon.", go = "settings:setup.wizard" },
        { de = "Schlafsack: Eine Leiste zeigt \"Gut erholt\" nur beim Liegen, ein X blendet sie aus. Standard aus.", en = "Sleeping bag: a bar shows the Well Rested stacks only while you lie, and an X hides it. Off by default.", go = "settings:sleepbag.main" },
        { de = "Berufstracker: Die Einkaufsliste hat einen Schließen-Knopf.", en = "Profession tracker: the shopping list has a close button.", go = "settings:professions.shopping" },
      },
      changed = {
        { de = "Einstellungen: Aus elf Reitern werden 43 in acht Gruppen, lange Karten klappen den Rest zu.", en = "Settings: the eleven tabs become 43 in eight groups, and long cards fold away the rest.", go = "settings" },
        { de = "Einrichtung: Der Assistent fragt nach Features statt nach Einzelschaltern.", en = "Setup: the wizard asks about features instead of single switches.", go = "settings:setup.wizard" },
        { de = "Fenster: Esc schließt alle Fenster des Addons, das zuletzt geöffnete zuerst.", en = "Windows: Esc closes every add-on window, the newest first." },
        { de = "Fensterstil: Neuinstallationen starten mit \"WoW Forever\", bestehende behalten ihre Wahl.", en = "Window style: fresh installs start with \"WoW Forever\", and existing installs keep their choice.", go = "settings:notes.main" },
        { de = "Weltkarte: Ein Klick auf einen Zonenübergang zeigt das Gebiet im Kartenfenster.", en = "World map: a click on a zone transition shows the area in the map window.", go = "map" },
        { de = "Raids: Barrow Deeps, Hyjal Summit und Onyxia's Lair sind Raids der Stufe 60 mit Datum 9. Dezember 2026.", en = "Raids: Barrow Deeps, Hyjal Summit and Onyxia's Lair are level 60 raids, dated December 9, 2026.", go = "instances" },
        { de = "Daten: Spielbuild 1.60.1.70888, Rezepte und Zauber der Saison der Entdeckungen sind entfernt.", en = "Data: game build 1.60.1.70888, and Season of Discovery recipes and spells are removed." },
        { de = "Erze und Kräuter: Etwa 1.900 Fundorte mehr, erstmals auch in Shen'dralas.", en = "Ores and herbs: about 1,900 more spots, for the first time also in Shen'dralas.", go = "gathering" },
      },
      fixed = {
        { de = "Schlafsack: Die Leiste erscheint nur beim Liegen, nicht mehr im Stehen.", en = "Sleeping bag: the bar shows only while you lie, no longer while you stand.", go = "settings:sleepbag.main" },
        { de = "Angelhilfe: Fische erscheinen mit Namen statt als Nummer.", en = "Fishing helper: fish show with their name instead of a number.", go = "settings:fishing.cast" },
        { de = "Instanzen: Gegenstände zeigen ihren Namen statt der Nummer.", en = "Instances: items show their name instead of the number.", go = "instances" },
        { de = "Tastatur: Enter und Leertaste wirken nur nach Tastaturbedienung eines Fensters.", en = "Keyboard: Enter and Space only act after you used the keyboard in a window." },
        { de = "Einstellungen: Escape verwirft die Eingabe in einem Textfeld.", en = "Settings: Escape discards the input in a text field.", go = "settings" },
        { de = "Fangjournal: Jeder Balken zeigt den echten Anteil und bleibt sichtbar.", en = "Catch journal: every bar shows its true share and stays visible.", go = "settings:fishing.journal" },
        { de = "Weltkarte: Das Panel \"Forever Guides\" liegt über dem Kartenrahmen.", en = "World map: the \"Forever Guides\" panel sits above the map frame.", go = "map" },
        { de = "Forever Chat: Gesperrte Nachrichten bleiben als Entwurf im Chatfeld.", en = "Forever Chat: blocked messages stay as a draft in the chat box.", go = "settings:foreverchat" },
      },
    },
    {
      version = "0.6.0",
      date = "2026-11-09",
      highlights = {
        { head = { de = "Layouts im Chat teilen", en = "Share layouts in chat" }, text = { de = "Ein Klick sendet ein Layout, ein Element oder eine Gruppe als Link, andere importieren es nach einer Vorschau.", en = "One click sends a layout, an element or a group as a link, and others import it after a preview." } },
        { head = { de = "Layouts pro Charakter oder Klasse", en = "Layouts per character or class" }, text = { de = "Ein neuer Dialog verwaltet alle Layouts, und du legst fest, wer sie nutzt, auch bei HUD-Fenstern.", en = "A new dialog manages all layouts, and you choose who uses them, HUD windows included." } },
        { head = { de = "Instanzen mit mehr Inhalt", en = "More to see in instances" }, text = { de = "Stufe von bis, fünf neue Dungeons, mehr Beute und Quests und ein Fenster mit Vorquests samt Marker und Karte.", en = "Level ranges, five new dungeons, more loot and quests, and a window with prequests, waypoints and a map button." } },
        { head = { de = "Elemente in Gruppen ziehen", en = "Drag elements into groups" }, text = { de = "Im Layout-Editor ziehst du Elemente in eine Gruppe und wieder heraus, mit Einfügelinie und Strg+Z für jeden Zug.", en = "In the layout editor you drag elements into a group and back out, with a drop line and Ctrl+Z for every move." } },
      },
      added = {
        { de = "Klassenlehrer: Die Seite hat ein Suchfeld \"Suchen\" (Platzhalter \"Name oder Ort\") wie die Berufslehrer. Es findet den Namen (Deutsch und Englisch), den Ort und die Zone eines Lehrers, Groß- und Kleinschreibung, Akzente, Umlaute und Apostrophe spielen keine Rolle, mehrere Wörter müssen alle vorkommen. Ein Zähler zeigt \"n von m Lehrern\" (Treffer von allen Lehrern der gewählten Klasse und Fraktion), ohne Treffer steht \"Kein Lehrer passt zu dieser Suche.\" Das Feld lässt sich mit Tab erreichen, Enter und Esc verlassen es.", en = "Class trainers: the page has a search field that finds a trainer by name, place or zone and shows how many trainers match." },
        { de = "Layout-Editor (Mauszeiger-Ring, HUD-Fenster, Erfahrungsleiste): \"Im Chat teilen\" gibt ein ganzes Layout, ein einzelnes Element oder eine Gruppe mit allen Unterelementen als kurzen Link in den Chat, den du wählst (Beispiel \"[Layout - Mein Ring (12)]\"). Der Knopf steht in der Kopfzeile neben \"Verwalten\", in jeder Zeile der Elementliste, im Panel des Elements, im Dialog \"Layouts verwalten\", auf den Einstellungsseiten von Ring und Erfahrungsleiste und auf jeder Fenster-Karte der HUD-Fenster. Andere Addon-Nutzer klicken den Link, sehen eine Vorschau (Name, Zahl der Elemente, bei Gruppen die Struktur, Absender) und importieren mit \"Importieren ...\" über den Import-Dialog des Editors, der noch einmal fragt. Gesendet wird nur auf deinen Klick und nur mit \"Senden\" bei den Chat-Links in den Einstellungen, empfangen nur mit \"Empfangen\", sonst bleibt es Text. Alternativ zeigt \"Als Text kopieren\" den Austauschtext.", en = "Layout editor: \"Share in chat\" sends a whole layout, one element or a group as a short link. Other players click it, see a preview and import it." },
        { de = "Mauszeiger-Ring: Das Element Aura prüft Satt für jede Nahrung. Der Schalter \"Jeder Satt-Buff zählt\" (Standard an) erscheint, sobald der gewählte Zauber ein Satt-Buff ist, und zählt jeden Satt-Buff nach ID und nach Name, aus: nur der gewählte. Neue Vorlage \"Satt (fehlt)\" mit Ring und Element.", en = "Mouse cursor ring: the aura element can check Well Fed for any food. New template \"Well Fed (missing)\" and a switch \"Any Well Fed buff counts\"." },
        { de = "Mauszeiger-Ring und HUD-Fenster: Bei den Elementen Aura (auch Proc) und Abklingzeit wählst du jetzt unter \"Rang\", ob der höchste Rang des gewählten Zaubers gilt (Standard, wie bisher) oder nur der Zauber mit der gewählten ID. Bestehende Layouts und Importe ohne den Wert bleiben beim höchsten Rang.", en = "Mouse cursor ring and HUD windows: aura and cooldown elements let you choose under \"Rank\" whether the highest rank or only the chosen spell ID counts." },
        { de = "Mauszeiger-Ring: Das Element Aura hat eine neue Quelle Waffenverzauberung für Gifte, Wetzsteine, Gewichtssteine, Öle, Köder und die Waffenbuffs des Schamanen (Flammenzunge, Frostbrand, Felsbeißer, Windzorn). Es zeigt Symbol, Restzeit im Zeitformat der Auren, Aufladungen als Stapel und die Farbe nach Restzeit. Du wählst die Haupthand, die Nebenhand oder eine beliebige Hand und eine Schwelle, unter der Ring und Zeit die niedrige Farbe bekommen.", en = "Mouse cursor ring: the aura element has a new source, Weapon enchantment, for poisons, stones, oils and shaman weapon buffs, with symbol, time left, charges and low color." },
        { de = "Mauszeiger-Ring und HUD-Fenster: Die Quelle Waffenverzauberung kennt auch die Bedingung Fehlt. Ein Ring in Warnfarbe erscheint, solange eine ausgerüstete Waffe keine Verzauberung trägt. Ein Schild, ein Gegenstand der Nebenhand oder eine leere Hand zählt nicht. Die Vorlage Waffenverzauberung (fehlt) legt ihn an.", en = "Mouse cursor ring and HUD windows: the Weapon enchantment source can warn while an equipped weapon has no enchantment. The preset \"Weapon enchantment (missing)\" sets it up." },
        { de = "Layout-Editor: Oben in der Seitenspalte steht eine Auswahl \"Layout\" mit dem geöffneten Layout. Sie öffnet eine Liste mit Suchfeld (Tippen sucht, Pfeil hoch und runter bewegt, Enter wählt, Esc schließt), das geöffnete Layout ist markiert. Daneben stehen \"Neu\", \"Duplizieren\" und \"Verwalten\".", en = "Layout editor: a \"Layout\" picker with a search box sits at the top of the side column, next to \"New\", \"Duplicate\" and \"Manage\"." },
        { de = "Layout-Editor: Der Knopf \"Verwalten\" öffnet den Dialog \"Layouts verwalten\" (Fenster mit eigener Größe, die mit dem Editor wächst) mit Suchfeld und einer Liste über die ganze Höhe. Jede Zeile hat Namen, Hinweiszeile, \"Öffnen\", \"Gilt für\", Umbenennen, Duplizieren und Löschen, der Knopf \"Neu\" steht unten. Bei HUD-Fenstern heißt die Liste \"Fenster\", sie zeigt jedes Fenster und seine Varianten, das Feld \"Gilt für\" steht dort bei jeder Variante.", en = "Layout editor: \"Manage\" opens the \"Manage layouts\" dialog with a search box and a list of all layouts, with rename, duplicate, delete and \"Applies to\" in every row." },
        { de = "Mauszeiger-Ring: Pro Layout lässt sich festlegen, wer es nutzt: \"Dieser Charakter\" oder \"Klasse\" (alle Charaktere derselben Klasse auf dem Konto, zum Beispiel alle Jäger). Es gilt der Reihe nach die Wahl für den Charakter, die Wahl für die Klasse, der Konto-Standard. Das Feld \"Gilt für\" steht in jeder Zeile des Dialogs \"Layouts verwalten\" und auf der Seite des Rings neben \"Layout für diesen Charakter\".", en = "Mouse cursor ring: for each layout you choose who uses it, \"This character\" or \"Class\". The character choice wins over the class choice, then the account default applies." },
        { de = "Layout-Editor: Unter der Auswahl steht, welches Layout dieser Charakter nutzt und warum, zum Beispiel \"Dieser Charakter nutzt: Standard-Ring (Klasse Jäger)\".", en = "Layout editor: a line under the picker says which layout this character uses and why." },
        { de = "Layout-Editor (Mauszeiger-Ring und HUD-Fenster): In der Elementliste steht vor dem Namen das Symbol dessen, was das Element zeigt: der gewählte Zauber, Gegenstand oder die Aura (auch die Quellen Waffenverzauberung und Satt), bei Abklingzeit auch ein getragener Gegenstand eines Platzes. Ist nichts gewählt oder das Symbol unbekannt, steht ein neutrales Typsymbol, eine Gruppe behält ihren Ordner. Ein Gegenstand, den das Spiel noch nicht geladen hat, bekommt sein Symbol nach, sobald die Daten da sind.", en = "Layout editor: the element list shows the symbol of the chosen spell, item or aura in front of each name." },
        { de = "Layout-Editor (Mauszeiger-Ring und HUD-Fenster): Einzelne Elemente und ganze Gruppen lassen sich kopieren. Der Knopf \"Kopieren\" steht in jeder Zeile der Elementliste und im Panel des Elements, Strg+C tut dasselbe. Bei einer Gruppe sind alle Unterelemente im Text, den du weitergeben kannst.", en = "Layout editor: single elements and whole groups can be copied with the \"Copy\" button or Ctrl+C and passed on as text." },
        { de = "Layout-Editor: Der Import erkennt kopierte Elemente. Er zeigt \"n Elemente\" oder \"Gruppe X mit m Unterelementen\", \"Einfügen\" setzt sie in das geöffnete Layout (Strg+Z macht es rückgängig), \"Stattdessen als neues Layout anlegen\" legt ein eigenes an. Passt es nicht in die 64 Elemente, ändert sich nichts und die Meldung nennt den freien Platz. Ein ganzes Layout und kopierte Elemente erkennen sich gegenseitig und sagen es.", en = "Layout editor: the import recognizes copied elements and inserts them into the open layout (Ctrl+Z undoes it) or creates a new layout from them." },
        { de = "Neue Seite Changelog im Addon-Fenster (Gruppe Addon): Sie zeigt, was sich in den letzten zehn Versionen geändert hat, in deiner Sprache, die neueste oben und aufgeklappt, mit den Abschnitten Neu, Geändert und Behoben. Ein Punkt am Eintrag der Seitenleiste zeigt neue Einträge, bis du die Seite geöffnet hast, und neue Versionen tragen die Marke Neu. Der Knopf \"Release-Link kopieren\" gibt die Adresse der Release-Seite zum Kopieren.", en = "New Changelog page in the add-on window: it shows what changed in the last versions, in your language. A sidebar dot and a New mark show changes you have not seen." },
        { de = "HUD-Fenster: Neues Auswahlfeld \"Sichtbar für\" auf der Fenster-Karte und im Abschnitt \"Fenster\" des Editors: \"Alle Charaktere\", \"Diese Klasse (Jäger)\", \"Nur dieser Charakter\" oder \"Nicht auf diesem Charakter\". Es gilt der Reihe nach die Wahl für den Charakter, für die Klasse, sonst die Regel für alle. Der Haken \"Sichtbar\" und \"Wann aktiv\" gelten zusätzlich. Fenster ohne Regel bleiben überall sichtbar.", en = "HUD windows: the new field \"Visible for\" decides per window whether all characters, a class or only this character see it." },
        { de = "HUD-Fenster: Ein Fenster kann mehrere Layouts haben, die Standardvariante und bis zu fünf weitere Varianten. Der Knopf \"Neue Variante\" im Abschnitt \"Fenster\" des Editors kopiert das geöffnete Layout in eine neue Variante. Im Dialog \"Layouts verwalten\" legst du pro Variante bei \"Gilt für\" fest, ob nur dieser Charakter oder alle Charaktere seiner Klasse sie zeichnen, sonst gilt die Standardvariante. Das Fenster behält Namen, Position, Skalierung und Sperre, nur der Inhalt wechselt. Die Zeile unter der Layout-Auswahl nennt die Variante dieses Charakters. Bestehende Fenster haben nur die Standardvariante und sehen aus wie vorher.", en = "HUD windows: a window can have up to five more layout variants, assigned per character or class in \"Manage layouts\". The window keeps its name, position and scale." },
        { de = "Layout-Editor (HUD-Fenster): Einzelne Elemente und Gruppen mit Unterelementen lassen sich auch in einer Variante eines Fensters kopieren, im Chat teilen und importieren, Export und Import alter Layout-Texte laufen unverändert.", en = "Layout editor (HUD windows): elements and groups can also be copied, shared in chat and imported in a variant of a window." },
        { de = "Layout-Editor (Mauszeiger-Ring und HUD-Fenster): Strg+Rechts rückt das gewählte Element in die Gruppe darüber ein, Strg+Links holt es aus seiner Gruppe. Die Knöpfe Einrücken und Ausrücken im Panel tun dasselbe.", en = "Layout editor: Ctrl+Right moves the selected element into the group above it, Ctrl+Left takes it out. The Indent and Outdent buttons in the panel do the same." },
        { de = "Changelog-Seite: Jede Version zeigt zuerst eine Kurzfassung mit den wichtigsten Punkten, die lange Liste mit Neu, Geändert und Behoben lässt sich per Knopf aufklappen.", en = "Changelog page: each version first shows a short summary of the key points. A button opens the full list of new, changed and fixed items." },
        { de = "Dungeons und Raids: Fünf neue Dungeons stehen in der Instanzenliste mit ihren Bossen (The Drowned City, Blackmaw Hold, Alcaz Prison, The Shaper's Terrace, Krol'dok Stronghold). Jede Instanz zeigt Spielerzahl und Eintrittsstufe.", en = "Dungeons and raids: five new dungeons are in the list with their bosses: The Drowned City, Blackmaw Hold, Alcaz Prison, The Shaper's Terrace and Krol'dok Stronghold." },
        { de = "Dungeons und Raids: Viele Instanzen zeigen mehr Bosse, mehr Beute und mehr Quests, dazu die Zugangsketten zu Dungeons und Raids.", en = "Dungeons and raids: many instances show more bosses, more loot and more quests, and the access chains that lead to a dungeon or raid." },
        { de = "Dungeons und Raids: Das Kästchen \"Nach Fraktion gruppieren\" ordnet die Liste in Allianz, Horde und Beide Fraktionen mit der Zahl je Gruppe. Eine Gruppe lässt sich ein- und ausklappen, das Addon merkt sich den Zustand.", en = "Dungeons and raids: the box Group by faction sorts the list into Alliance, Horde and both factions with a count. Each group can be collapsed, the add-on remembers it." },
        { de = "Dungeons und Raids: Angekündigte Raids, die noch nicht erreichbar sind (zum Beispiel Barrow Deeps), tragen in Liste und Kopfzeile die Marke \"angekündigt\" und haben keine Eintrittsstufe.", en = "Dungeons and raids: raids that are announced but not reachable yet, such as Barrow Deeps, carry the mark Announced and have no entry level." },
        { de = "Instanzen: Ein Klick auf eine Quest öffnet ein Fenster mit der Kette der Vorquests, je Schritt mit Stufe, \"ab Stufe\", Erfahrung, Geber mit Zone, einem Knopf \"Marker setzen\" und einem Knopf \"Karte\". Fehlt der Ort, sind die Knöpfe aus und der Text sagt, was fehlt. Pfeiltasten, Tab, Enter und Esc funktionieren.", en = "Instances: clicking a quest opens a window with its chain of prerequisite quests, with a waypoint button and a map button for every step." },
        { de = "Instanzen: Die Quests der Instanzen (Questketten und Zugangsketten) stehen in einem eigenen Daten-Addon, das beim ersten Öffnen der Seite Instanzen von selbst lädt. Fehlt es oder ist es ausgeschaltet, zeigt die Seite die Instanzen ohne Quests mit einem Hinweis. Im Kampf wartet das Laden bis zum Kampfende.", en = "Instances: the quests come from a data add-on of their own that loads when you first open the Instances page. Without it the page shows the instances and a note." },
        { de = "Instanzen: Bosse ohne Symbol zeigen jetzt ein kleines 3D-Porträt, auf der Instanzenseite und in der Dungeonkarte. Das bisherige Platzhalter-Symbol bleibt als Rückfall.", en = "Bosses without a symbol now show a small 3D portrait on the instances page and in the dungeon map, the placeholder stays as fallback." },
      },
      changed = {
        { de = "Forever Chat: Die Fenster-Deckkraft (Einstellungen des Chats, gilt für Messenger und Mini-Fenster) geht jetzt von 0 bis 100 Prozent, vorher von 60 bis 100. Bei kleinen Werten verblasst nur der Fensterhintergrund, Text, Kopfzeile, Knöpfe und Eingabefeld bleiben voll sichtbar, bei 0 Prozent zeigen Titel (mit Schatten) und Rand das Fenster weiter an und es lässt sich am Titel greifen. Gespeicherte Werte von 60 bis 100 bleiben gültig, der Standard bleibt 92.", en = "Forever Chat: the window opacity now runs from 0 to 100 percent. At low values only the background fades, text and buttons stay visible, and at 0 percent title and border still show." },
        { de = "Mauszeiger-Ring: Tooltips, Menüs und Dropdowns werden nicht mehr vom Ring überdeckt. Der Standard der Ebene ist jetzt \"Vollbild\" (vorher \"Tooltip (oben)\"): der Ring liegt über den Spielfenstern und unter Menüs, Dialogen und Tooltips. Die Ebene \"Tooltip (oben)\" gibt es nicht mehr, ein gespeicherter Wert wird zum neuen Standard.", en = "Mouse cursor ring: the ring no longer covers tooltips, menus and dropdowns. The layer default is now \"Fullscreen\" and the layer \"Tooltip (top)\" is gone." },
        { de = "Tooltips des Addons liegen immer in der obersten Ebene. HUD-Fenster lagen schon unter jedem Tooltip.", en = "Tooltips of the add-on always sit in the top layer." },
        { de = "Layout-Editor: Die schmale Liste der Layouts in der Seitenspalte fällt weg (bei einem kleinen Fenster waren nur zwei Zeilen sichtbar, das Suchen war mühsam). Das Band ist niedriger, die Elementliste, die Vorschau und die Einstellungen bekommen mehr Platz, auch in der Mindestgröße.", en = "Layout editor: the narrow layout list in the side column is gone, the picker replaces it. The element list, preview and settings get more room." },
        { de = "Daten: Stand des Spielbuilds 1.60.1.70862 (2026-11-07): Zauber, Stufen und Flugzeiten (Shank mit Rang 1 und 2, eine Flugstrecke um 3 Yards kürzer). Die Info-Seite nennt den neuen Stand.", en = "Game data: state of game build 1.60.1.70862 (2026-11-07) with new spells, levels and flight times. The info page shows the new state." },
        { de = "Layout-Editor (Mauszeiger-Ring und HUD-Fenster): Elemente und ganze Gruppen lassen sich in der Liste per Ziehen sauber in eine Gruppe, innerhalb einer Gruppe und wieder heraus verschieben, mit Einfügelinie und Strg+Z für jeden Zug.", en = "Layout editor: elements and whole groups can be dragged into a group, within it and back out in the list, with a drop line and Ctrl+Z for each move." },
        { de = "Dungeons und Raids: Alle Instanzen zeigen die Stufe von bis (\"Stufe 24 bis 29\") in der Liste, in der Kopfzeile, im Reiter Info, im Tooltip der Pins auf Weltkarte und Addon-Karte. Fehlt eine Seite, steht sie als Fragezeichen mit einem benannten Hinweis. Die Eintrittsstufe und die empfohlene Stufe stehen getrennt davon.", en = "Dungeons and raids: every instance shows its level range, for example Level 24 to 29, in the list, the header, the Info tab and the map pins. A missing end shows as a question mark." },
        { de = "Dungeons und Raids: Die Suche nach einer Stufe (zum Beispiel \"40\") findet jede Instanz, deren Stufenbereich oder Eintrittsstufe sie enthält, im Filter der Seite und in der Suche des Addons.", en = "Dungeons and raids: searching a level, for example 40, finds every instance whose level range or entry level contains it." },
        { de = "Dungeons und Raids: Sortiert die Liste \"nach Stufe\", gilt zuerst der Anfang, dann das Ende des Bereichs, Instanzen ohne Stufe stehen am Ende.", en = "Dungeons and raids: sorting the list by level uses the start and then the end of the range. Instances without a level come last." },
        { de = "Instanzen: Die Quests stehen in den Gruppen Allianz, Horde und Beide mit einem Filter nach Fraktion und je Gruppe nach Stufe, zuerst die direkten Dungeon-Quests, die Vorquests eingeklappt darunter.", en = "Instances: quests are grouped by Alliance, Horde and both with a faction filter and sorted by level. Dungeon quests come first, prerequisite quests are folded below." },
        { de = "Dungeons und Raids: Ein Boss ohne Symbol und ohne Porträt zeigt überall (Bossliste, Bossreiter, Reiter Items) dasselbe Platzhalter-Symbol, statt einer Lücke oder eines Buchstabens im Kreis.", en = "Dungeons and raids: a boss without a symbol or portrait shows the same placeholder icon everywhere instead of a gap or a letter." },
        { de = "Dungeons und Raids: Die Namen der Instanzen folgen dem Spiel (Deutsch und Englisch). Die bisherigen Namen bleiben als Suchbegriff erhalten.", en = "Dungeons and raids: instance names follow the game in German and English. The former names still work as search terms." },
        { de = "Changelog: In der Langfassung stehen Abschnittstitel und Eintragsüberschriften jetzt groß in Akzentblau, und der Knopf \"Alle Änderungen anzeigen\" ist deutlicher.", en = "Changelog: in the full list the section titles and entry headlines are now large and accent blue, and the \"Show all changes\" button stands out." },
      },
      fixed = {
        { de = "Aussehen: Der Farbenblind-Modus setzt das gewählte Aussehen nicht mehr zurück. Vorher schaltete er den Fensterstil \"WoW Forever\" (Metallrahmen, Fels, Goldtitel, Goldfarben) sofort auf \"Flach\", obwohl der Fensterstil weiter als gewählt angezeigt wurde. Jetzt tauscht der Modus nur das Paar Rot und Grün gegen Blau und Orange, Fensterstil, Farbschema und Akzentfarbe bleiben, in beiden Reihenfolgen und beim Ausschalten. Nur der Hohe Kontrast nutzt weiterhin \"Flach\".", en = "Look: colorblind mode no longer resets the chosen window style. It now only swaps the red and green pair for blue and orange." },
        { de = "Volkszauber der Orcs, Untoten und Gnome (Kochendes Blut, Zähigkeit, Fluch brechen, Kannibalismus, Wille der Verlassenen, Unterwasseratmung, Entfesselungskünstler, Technologist) gehören keiner Klasse mehr. Der Makro-Prüfer warnt bei ihnen nicht mehr fälschlich \"gehört nicht zur Klasse\", und die Zauberauswahl im Makro-Editor zeigt sie für jede Klasse.", en = "Racial spells of Orcs, Undead and Gnomes belong to no class any more. The macro checker no longer warns wrongly, and the spell picker shows them for every class." },
        { de = "Suche: Instanzen lassen sich in der Suche und im Instanzfilter wieder über ihre alten Namen und Abkürzungen finden, zum Beispiel \"Tiefschwarze Grotte\" oder \"BFD\".", en = "Search: instances can be found again by their former names and abbreviations in search and instance filter, for example \"Tiefschwarze Grotte\" or \"BFD\"." },
      },
    },
    {
      version = "0.5.5",
      date = "2026-11-09",
      highlights = {
        { head = { de = "Vorräte im Blick", en = "Supplies at a glance" }, text = { de = "Ein neues Element zeigt, wie viele Tränke, Gifte oder Nahrung du dabei hast, mit Farbwechsel bei wenig.", en = "A new element shows how many potions, poisons or food you carry and changes color when you run low." } },
        { head = { de = "Gildendaten ohne Neustart", en = "Guild data without a restart" }, text = { de = "Wer Empfangen einschaltet, sieht die Daten der Gilde nach wenigen Sekunden.", en = "Switch on receiving and the data of your guild shows up within a few seconds." } },
        { head = { de = "Teilen mit Statuszeile", en = "Sharing with a status line" }, text = { de = "Jede Funktion zeigt, was gesendet und gehört wurde, und nennt den Grund, wenn nichts passiert.", en = "Each function shows what was sent and heard, and says why when nothing happens." } },
        { head = { de = "Weniger Fehlermeldungen", en = "Fewer error messages" }, text = { de = "Verborgener Chattext und langes Halten einer Listenzeile lösen keine Fehler mehr aus.", en = "Hidden chat text and holding a list row no longer cause errors." } },
      },
      added = {
        { de = "Neues Element \"Gegenstandsanzahl\" für den Mauszeiger-Ring und die HUD-Fenster: zeigt, wie viele Exemplare eines Gegenstands du dabei hast (Tränke, Gifte, Munition, Reagenzien, Nahrung, Material), mit Zielmenge und Farbwechsel bei wenig.", en = "Item count: a new element for the mouse ring and HUD windows shows how many of an item you carry, with an optional goal and a color change when the number is low." },
        { de = "Neue Vorlagen \"Verbrauchsgut mit Anzahl\" (Ring) und \"Eine Gegenstandsanzahl\" (HUD-Fenster).", en = "Item count: new templates \"Consumable with count\" for the ring and \"One item count\" for HUD windows." },
        { de = "Teilen: Der neue Befehl /fg diag share öffnet ein Fenster zum Kopieren und nennt je Funktion, was gesendet, gehört und verworfen wurde, für Fehlermeldungen.", en = "Sharing: the new command /fg diag share opens a window to copy from and lists per function what was sent, heard and dropped, for bug reports." },
      },
      changed = {
        { de = "Teilen: Wer Empfangen für eine Gildenfunktion einschaltet (Gildenkarte, Anwesenheit, Logos, Itemlevel, Berufe, Handwerker), fragt die Gilde einmal \"Wer ist da?\" und bekommt die Daten der Sender innerhalb weniger Sekunden, ohne Neustart. Die Frage enthält nichts über dich. Sie geht nur mit Empfangen an hinaus, wird nur mit Senden an beantwortet und höchstens einmal je Funktion und Minute.", en = "Sharing: when you switch on receiving for a guild function, the add-on asks the guild once who is there and shows the senders' data within seconds. The question contains nothing about you." },
        { de = "Teilen: Das Einschalten von Senden schickt die Erstmeldung nach 1 bis 3 Sekunden, nicht erst nach dem langen Spreizen. Itemlevel und Berufe warten dafür nicht mehr bis zu 30 Minuten.", en = "Sharing: switching on sending now sends the first message after 1 to 3 seconds. Item level and professions no longer wait up to 30 minutes." },
        { de = "Teilen: Jede Funktion zeigt auf der Seite Teilen eine Statuszeile (Senden, Empfangen, zuletzt gesendet, zuletzt gehört, Mitspieler gehört) und nennt den Grund, wenn nichts passieren kann (keine Gilde, niemand gehört, Kampf, Einschränkung, Sendegrenze, Probekonto).", en = "Sharing: each function shows a status line on the Share page and names the reason when nothing can happen, such as no guild, combat or the send limit." },
        { de = "Teilen: Die Sammelschalter nennen, für wie viele Funktionen dieser Charakter eine eigene Einstellung hat und der Schalter dort nur ihn ändert.", en = "Sharing: the bulk switches show for how many functions this character has its own setting, and there the switch changes only this character." },
        { de = "Einwilligungstexte und Datenschutz-Info nennen die Nachfrage \"Wer ist da?\" ehrlich (Deutsch und Englisch). Der Satz zur Privatsphäre beim Handwerker-Text (nichts geht an Gruppe, Freunde oder Fremde) ist zurück.", en = "Consent texts and the privacy info now state plainly that the add-on asks the guild who is there, and the privacy sentence in the crafter text is back." },
      },
      fixed = {
        { de = "Chat und Teilen: Ein vom Spiel verborgener (geheimer) Chattext löste Fehlermeldungen aus, zum Beispiel bei der Antwort \"Kein Spieler namens ... gefunden\" (Teamchat, Teilen), beim Beutefang, bei Einladungs-Flüstern und bei Links. Solche Texte werden jetzt nie mehr gelesen oder verglichen und die Zeile wird übersprungen.", en = "Chat and sharing: a chat text that the game hides no longer causes errors, for example on the \"No player named\" answer, in loot capture, on invite whispers and on links." },
        { de = "Listen mit Ziehen zum Umsortieren: Hielt man eine Zeile länger als einen Augenblick gedrückt, kam der Fehler \"attempt to compare boolean with number\". Das automatische Scrollen am Listenrand las den falschen Rückgabewert der Mausposition und scrollt jetzt richtig. Auch eine fehlende Mausposition bricht nichts mehr ab.", en = "Lists with drag to reorder: holding a row for a moment no longer raises an error, and the list scrolls correctly at its edge." },
        { de = "Oberfläche ausblenden (Alt+Z): Die Erfahrungsleiste verschwand danach für immer, obwohl die Einstellung an war, weil das Ausblenden als Schließen durch dich galt. Jetzt kommt sie mit der Oberfläche zurück, genau wie vorher.", en = "Hiding the interface (Alt+Z): the experience bar no longer stays gone for good, it comes back with the interface." },
        { de = "Oberfläche ausblenden (Alt+Z): Das kleine Chat-Fenster behält seinen Chat, und das Hauptfenster beendet dabei weder den Bearbeitungsmodus der Navigation noch eine laufende Tour.", en = "Hiding the interface (Alt+Z): the small chat window keeps its chat, and the main window no longer ends the navigation edit mode or a running tour." },
        { de = "Erfahrungsleiste: Die Schicht für ausgeruhte EP ist jetzt ein Streifen am unteren Rand, damit die fertigen Quests ihre volle Länge hinter den aktuellen EP behalten.", en = "Experience bar: the rested XP layer is now a strip along the bottom, so completed quests keep their full length behind your current XP." },
        { de = "Klassen & Völker: Der Himmelsgeborene der Windformer (Horde) kann im Spiel kein Magier sein, das Addon bot ihn dafür an. Jetzt stimmen beide Himmelsgeborenen-Völker mit der Charaktererstellung überein: Hoher Orden Krieger, Jäger, Schurke, Magier, Druide, Windformer Krieger, Jäger, Schurke, Schamane, Druide.", en = "Classes and races: the Horde Skyborne (Windshaper) can no longer be picked as a mage, both Skyborne races now match character creation." },
        { de = "Volksfähigkeiten der Himmelsgeborenen: Read Leyline und Skysight sind aktive Fähigkeiten mit den Werten des Spiels (Lebens- und Manaregeneration 50% für 15 Sek., Lauftempo 15% für 30 Sek.), Wind Blessed gibt 2% Tempo.", en = "Skyborne racials: Read Leyline and Skysight are active abilities (50% health and mana regeneration for 15 sec, 15% movement speed for 30 sec), Wind Blessed gives 2% haste." },
        { de = "Himmelsgeborene: Waffenfertigkeiten und Stufen-Übersicht erkennen einen Himmelsgeborenen als eigenes Volk (Fraktion unterscheidet Hoher Orden und Windformer), die Waffenseite wählt es vor.", en = "Skyborne: weapon skills and the levels overview recognize a Skyborne character as its own race, and the weapons page preselects it." },
        { de = "Karte: Der Schalter Skyborne-Volk startet an, wenn der Charakter ein Himmelsgeborener ist.", en = "Map: the Skyborne race switch starts on for a Skyborne character." },
        { de = "Teilen: Wurde die Gilde nach dem Login erst später bekannt, blieben Gildenkarte, Anwesenheit, Logos, Itemlevel, Berufe und Handwerker stumm, bis ein Ladebildschirm kam. Jetzt starten sie, sobald die Gilde und die Gildenliste da sind, mit Wiederholung nach 2, 5, 10, 20, 40 und 60 Sekunden.", en = "Sharing: when the guild became known only after login, the guild functions stayed silent until a loading screen. They now start as soon as the guild and its member list are ready." },
        { de = "Teilen: Ein Präfix, das das Spiel bei der Anmeldung ablehnt, wird beim nächsten Schalter, Login und Ladebildschirm erneut angemeldet.", en = "Sharing: a registration that the game refuses is repeated at the next switch, login and loading screen." },
        { de = "Teilen: Wer Empfangen erst später einschaltete, wartete auf den nächsten Takt der Sender (bis 2 Minuten bei der Gildenkarte, bis 40 Minuten bei Marke und Logos, 30 Minuten bei Itemlevel und Berufe) und sah deshalb nichts bis zu deren Neustart.", en = "Sharing: switching on receiving later no longer means waiting for the next beat of the senders, which could take up to 40 minutes." },
        { de = "Anfrage zum Gildeneinladen: Der Knopf \"Befehl kopieren\" öffnet ein Fenster und trägt jetzt wie die übrigen Knöpfe dieser Art das Symbol Öffnen.", en = "Guild invite request: the \"Copy command\" button now carries the Open symbol like the other buttons that open a window." },
        { de = "Stufen-Übersicht: Beidhändigkeit (Jäger und Krieger Stufe 20, Schurke Stufe 10), Panzer (Jäger und Schamane Stufe 40) und Plattenpanzer (Krieger und Paladin Stufe 40) fehlten in der Liste, obwohl der Klassenlehrer sie beibringt. Sie stehen jetzt mit Lehrerpreis auf der richtigen Stufe, Waffen der Waffenmeister bleiben auf ihrer eigenen Seite. Auch Segen der Könige (Paladin Stufe 20) fehlte, weil ein anderer Eintrag derselben Stufe ihn verdeckte.", en = "Levels overview: Dual Wield, Mail, Plate Mail and Blessing of Kings were missing although the class trainer teaches them. They now appear at the right level with the trainer price." },
        { de = "Stufen-Übersicht: Der Hexenmeister-Zauber heißt im Spiel Omen der Verdammnis (Bane of Doom), die Liste zeigt jetzt diesen Namen mit dem richtigen Zauber, damit er als gelernt erkannt wird.", en = "Levels overview: the warlock spell Bane of Doom now shows the name used in the game and is recognized as learned." },
        { de = "Die Befehle /fg diag share und /fg diag chat zeigten bei ausgeschalteten Rückmeldungen nichts an. Sie öffnen jetzt ein Fenster, aus dem du den Text kopieren kannst.", en = "The commands /fg diag share and /fg diag chat showed nothing with feedback off. They now open a window you can copy the text from." },
      },
    },
    {
      version = "0.5.4",
      date = "2026-11-06",
      highlights = {
        { head = { de = "Gildenmanager im Forever-Client", en = "Guild manager on the Forever client" }, text = { de = "Das Spiel lässt Addons die Gilde nicht ändern, darum zeigt jeder Schritt den Befehl zum Kopieren.", en = "The game does not let add-ons change the guild, so each step shows a command to copy." } },
        { head = { de = "Lauf ohne Stillstand", en = "No more stalling" }, text = { de = "Der Gildenmanager wartet nicht mehr an der Gildenliste, sondern geht von selbst weiter.", en = "The guild manager no longer waits at the guild list and goes on by itself." } },
        { head = { de = "Esc im Kampf", en = "Esc in combat" }, text = { de = "Fenster lösen keine blockierte Aktion mehr aus und schließen nach dem Kampf.", en = "Windows no longer trigger a blocked action and close when the combat ends." } },
      },
      changed = {
        { de = "Gildenmanager im Forever-Client: Das Spiel lässt Addons die Gilde nicht ändern, jeder Schritt öffnet deshalb ein Feld mit dem Befehl zum Kopieren. Notizen und Rangsprünge gibt es dort nicht.", en = "Guild manager on the Forever client: the game does not let add-ons change the guild, so each step opens a box with the command to copy. Notes and rank jumps are not offered there." },
      },
      fixed = {
        { de = "Gildenmanager: Der Lauf bleibt nicht mehr bei \"Wartet auf die Gildenliste\" stehen, er geht von selbst weiter, sobald die Liste frisch ist.", en = "Guild manager: the run no longer stops at waiting for the guild list, it goes on by itself once the list is fresh." },
        { de = "Fenster lösen beim Drücken von Esc im Kampf keine blockierte Aktion mehr aus, sie schließen nach dem Kampf.", en = "Windows no longer trigger a blocked action when you press Esc in combat, they close when the combat ends." },
        { de = "Spielermenü: Der Eintrag für die Gildeneinladung im Forever-Client löst keinen Fehler mehr aus, wenn das Spiel den Namen eines Spielers verbirgt.", en = "Player menu: the guild invite entry on the Forever client no longer raises an error when the game hides a player's name." },
      },
    },
    {
      version = "0.5.3",
      date = "2026-11-06",
      highlights = {
        { head = { de = "Einladungen im Forever-Client", en = "Invites on the Forever client" }, text = { de = "Das Spiel nimmt Gildeneinladungen nur an, wenn du sie selbst eingibst, ein Feld liefert den Befehl.", en = "The game only takes a guild invite that you enter yourself, so a box gives you the command." } },
        { head = { de = "Einladen aus dem Spielermenü", en = "Invite from the player menu" }, text = { de = "Ein neuer Eintrag öffnet das Feld mit dem Befehl, ein Schalter öffnet es bei jeder Anfrage.", en = "A new entry opens the box with the command, and a switch opens it for every request." } },
        { head = { de = "Neuladen in Gruppen", en = "Reload in groups" }, text = { de = "Der Speichern-Knopf lädt jetzt auch aus der Nachfrage in einer Gruppe neu.", en = "The save button now reloads from the question that appears in a group." } },
      },
      changed = {
        { de = "Einladungen per Flüstern: Im Forever-Client nimmt das Spiel eine Gildeneinladung nur an, wenn du sie selbst eingibst. Der Knopf öffnet ein Feld mit dem Befehl zum Kopieren, und der Chat nennt die Schritte.", en = "Whisper invites: on the Forever client the game only takes a guild invite that you enter yourself. The button opens a box with the command to copy, and the chat tells you the steps." },
        { de = "Einladungen per Flüstern: Im Forever-Client bekommen die Spielermenüs einen Eintrag, der das Feld mit dem Befehl öffnet, und ein neuer Schalter öffnet es bei jeder Anfrage (standardmäßig aus).", en = "Whisper invites: on the Forever client the player menus get an entry that opens the box with the command, and a new switch opens that box at every request (off by default)." },
      },
      fixed = {
        { de = "Speichern-Knopf: Das Neuladen funktioniert jetzt auch aus der Nachfrage in einer Gruppe, statt mit dem Hinweis zu enden, das Spiel habe es blockiert.", en = "Save button: the reload now works from the question that appears in a group, instead of ending in the notice that the game blocked it." },
      },
    },
    {
      version = "0.5.2",
      date = "2026-11-06",
      highlights = {
        { head = { de = "Speicher-Erinnerung ist aus", en = "Save reminder is off" }, text = { de = "Die Meldung über ungesicherte Daten erscheint nur noch, wenn du sie einschaltest.", en = "The notice about unsaved data only appears when you switch it on." } },
        { head = { de = "Wieder einschaltbar", en = "Can be switched back on" }, text = { de = "Das Update hat sie einmal ausgeschaltet, unter Einstellungen, Speichern schaltest du sie wieder ein.", en = "The update turned it off once, and you can turn it on again under Settings, Save." } },
      },
      changed = {
        { de = "Speicher-Erinnerung: Die Benachrichtigung über ungesicherte Daten mit dem Neuladen-Knopf ist jetzt standardmäßig aus und wurde beim Update einmal ausgeschaltet. Unter Einstellungen, Speichern lässt sie sich einschalten.", en = "Save reminder: the notice about unsaved data with its reload button is now off by default and was switched off once on update. Turn it on in Settings under Saving to be reminded." },
      },
    },
    {
      version = "0.5.1",
      date = "2026-11-05",
      highlights = {
        { head = { de = "Gildeneinladung ohne Warnung", en = "Guild invite without a warning" }, text = { de = "Das Fenster des Spiels fragt zuerst und sendet die Einladung nach deiner Bestätigung.", en = "The game's own window asks first and sends the invite after you confirm." } },
        { head = { de = "Stichwörter zählen einmal", en = "Keywords count once" }, text = { de = "Ein doppelt getipptes Stichwort wie ginvginv gilt jetzt nur einmal.", en = "A keyword typed twice, such as ginvginv, now counts once." } },
      },
      fixed = {
        { de = "Einladungen per Flüstern: Im Forever-Client zeigt die Gildeneinladung keine Blockade-Warnung mehr. Das Fenster des Spiels fragt zuerst und sendet die Einladung nach deiner Bestätigung.", en = "Whisper invites: on the Forever client the guild invite no longer shows a blocked warning. The game's own window asks first and sends the invite when you confirm." },
        { de = "Einladungen per Flüstern: Ein Stichwort, das doppelt im Einstellungsfeld stand, etwa ginvginv, zählt jetzt einmal.", en = "Whisper invites: a keyword that ended up typed twice in the settings field, such as ginvginv, now counts once." },
      },
    },
    {
      version = "0.5.0",
      date = "2026-11-04",
      highlights = {
        { head = { de = "Eigene HUD-Fenster", en = "Your own HUD windows" }, text = { de = "Platziere Fenster frei auf dem Bildschirm und fülle sie im Layout-Editor.", en = "Place windows anywhere on the screen and fill them in the layout editor." } },
        { head = { de = "Forever Chat als Messenger", en = "Forever Chat messenger" }, text = { de = "Ein Fenster für Flüstern, Gruppe, Gilde, Raid und Kanäle mit Reitern und Zähler für Ungelesenes.", en = "One window for whispers, group, guild, raid and channels, with tabs and unread counts." } },
        { head = { de = "Abklingzeiten und Auren am Zeiger", en = "Cooldowns and auras at the cursor" }, text = { de = "Zauber, Gegenstände und Buffs erscheinen als Ring, Quadrat oder Balken direkt am Mauszeiger.", en = "Spells, items and buffs show up as a ring, a square or a bar right at your mouse cursor." } },
        { head = { de = "GildenManager mit Regeln", en = "GildenManager with rules" }, text = { de = "Zwölf Vorlagen schlagen Beförderungen oder Entfernen vor, du bestätigst jeden Schritt.", en = "Twelve templates suggest promotions or removals, and you confirm every step." } },
      },
      added = {
        { de = "HUD-Fenster: Eigene Fenster liegen frei auf dem Bildschirm und werden im Layout-Editor gefüllt. Der Befehl /fg hudfenster legt sie an, bearbeitet, sperrt und listet sie, eine Einstellungsseite zeigt die Karten.", en = "HUD windows: place your own windows on the screen and fill them in the layout editor. /fg hudwindow creates, edits, locks and lists them, and a settings page holds the cards." },
        { de = "HUD-Fenster: Jedes Fenster hat beim Darüberfahren einen Zahnrad-Knopf, einen Knopf Duplizieren und ein Feld Ebene (hinter, auf einer Höhe mit oder über den Fenstern des Spiels). Ein angepinntes Fenster lässt Klicks durch.", en = "HUD windows: every window has a gear button on mouse over, a Duplicate button and a Layer field (behind, level with or above the game's panels). A pinned window lets the mouse click through it." },
        { de = "HUD-Fenster: Ein Abschnitt Fenster im Layout-Editor zeigt Sichtbarkeit, Anpinnen, X, Y und Skalierung für den aktuellen Charakter, dazu ein Knopf, der die Position in die Bildschirmmitte zurücksetzt.", en = "HUD windows: a Window section in the layout editor shows visibility, pinning, X, Y and scale for the current character, with a button that resets the position to the screen center." },
        { de = "Layout-Editor: Gruppen ordnen Elemente als Reihe, Spalte, Raster, Kreis oder frei an. Eine Gruppe lässt sich hinzufügen, die Auswahl mit Strg+G umhüllen, und Elemente werden in einem Baum zum Auf- und Zuklappen hinein- und herausgezogen.", en = "Layout editor: groups arrange elements as a row, column, grid, circle or freely. Add a group, wrap the selection with Ctrl+G, and drag elements in and out of a collapsible tree." },
        { de = "Layout-Editor: Das Fenster wird am Eckgriff in der Größe geändert (die Größe wird gespeichert), die Eigenschaften von Aura und Abklingzeit lassen sich einklappen, und es gibt Neu, Duplizieren und Als neu speichern.", en = "Layout editor: resize the window at the corner grip (the size is saved), fold the property sections of Aura and Cooldown, and use New, Duplicate and Save as new." },
        { de = "Mauszeiger-Ring: Das Element Abklingzeit zeigt Zauber, Pet-Zauber und Gegenstände (Schmuckstücke, Tränke) als Ring, Quadrat oder Balken, mit Aufladungen, Zeittext, Farbe nach Restzeit und einem Puls bei Bereitschaft.", en = "Mouse cursor ring: the Cooldown element shows spells, pet spells and items (trinkets, potions) as a ring, square or bar, with charges, time text, color by remaining time and a pulse when ready." },
        { de = "Mauszeiger-Ring: Das Element Aura zeigt einen Buff oder Debuff auf dir, Ziel, Fokus oder Pet oder das Leuchten eines Procs, mit Stapeln und Zeittext. Es kann auch nur erscheinen, solange die Aura fehlt.", en = "Mouse cursor ring: the Aura element shows a buff or debuff on you, target, focus or pet, or a proc glow, with stacks and time text. It can show while the aura is missing." },
        { de = "Mauszeiger-Ring: Im Kampf nutzt das Element Aura die Aura-Anzeige des Spiels oder zählt die Zeit selbst, wenn das Spiel sie verbirgt. Die Einstellung Anzeige im Kampf lässt dir die Wahl.", en = "Mouse cursor ring: in combat the Aura element uses the game's own aura display, or counts the time itself when the game hides it. The Display in combat setting lets you choose." },
        { de = "Mauszeiger-Ring: Eine Einstellung Anzeigen (immer, unter einer Restzeit, nur solange es läuft, nur wenn bereit) und eine Einstellung Zeitformat (automatisch, Sekunden, Uhr, kompakt) gelten für Abklingzeiten und Auren.", en = "Mouse cursor ring: a Show setting (always, only below a time left, only while it runs, only when ready) and a Time format setting (automatic, seconds, clock, compact) apply to cooldowns and auras." },
        { de = "Wann aktiv: HUD-Fenster und Ring nutzen die Schalter An, Egal und Aus für Kampf, Instanz, Gruppe, Reittier, Fahrzeug und Ziel. Klasse und Charakter lassen sich ebenfalls wählen.", en = "When active: HUD windows and the ring use On, Any and Off switches for combat, instance, group, mount, vehicle and target. Class and character can be chosen too." },
        { de = "Pro Charakter: Der Ring kann für jeden Charakter ein eigenes Layout und einen eigenen An- oder Aus-Zustand haben, und eine Zeile auf der Ring-Seite zeigt eine Überschreibung an und setzt sie zurück.", en = "Per character: the ring can use its own layout and on or off state for each character, and a line on the ring page shows an override and resets it." },
        { de = "Minimap: Erz- und Kräuterfundorte erscheinen als Pins auf der Minimap, mit Größe, Deckkraft, Verhalten am Rand und einem Nahbereich, der nur Kreise zeigt. In Instanzen sind die Pins ausgeblendet.", en = "Minimap: ore and herb nodes appear as pins on the minimap, with size, opacity, edge behavior and a close range that shows circles only. Pins are hidden in instances." },
        { de = "Farm-HUD: Ein Farm-Modus vergrößert die echte Minimap über die Bildschirmmitte, mit deinen Pins, einem Kompass und einem Sammelring. Er lässt sich mit /fg farmhud, einer Tastenbelegung oder der Karte Farm-HUD schalten.", en = "Farm HUD: a farm mode enlarges the real minimap over the screen center with your pins, a compass and a gathering ring. Switch it with /fg farmhud, a key binding or the Farm HUD card." },
        { de = "Erfahrungsleiste: Neue Platzhalter zeigen, woher die EP der Sitzung kommen (Kills, Quests, Entdeckungen), dazu Kills pro Stunde, EP pro Kill und Gegner bis zum Level. Die Vorlage Ausführlich nutzt sie.", en = "Experience bar: new placeholders show where your session XP comes from (kills, quests, exploration) and kills per hour, XP per kill and mobs to level. The Detailed preset uses them." },
        { de = "Zonenübergänge: Das Addon liefert 42 geprüfte Übergänge zwischen Zonen mit, 24 geschätzte Pfeile sind entfernt.", en = "Zone transitions: 42 checked transitions between zones ship with the add-on, and 24 estimated arrows were removed." },
        { de = "Berufsroute: Schritte vor dem Start-Skill und nach dem Ziel-Skill sind eingeklappt und öffnen sich per Klick. Jeder Lehrer mit Position hat neben dem Karten-Knopf einen Wegpunkt-Knopf.", en = "Profession route: steps before the start skill and after the target skill are collapsed and open with a click. Each trainer with a position has a waypoint button next to the map button." },
        { de = "Forever Chat: Ein Messenger-Fenster für Flüstern, Gruppe, Teams, Gilde, Raid und Kanäle, mit Reitern und Ungelesen-Zahlen. Es ist ein eigenes Addon, standardmäßig aus, und wird unter Addons eingeschaltet.", en = "Forever Chat: a messenger window for whispers, group, teams, guild, raid and channels, with tabs and unread counts. It is its own add-on, off by default, and you switch it on under Addons." },
        { de = "Forever Chat: Er nimmt alle Chatquellen auf, auch Sagen, Schreien, Emotes, Battle.net-Flüstern und Gemeinschaftskanäle. Flüstern und Battle.net-Chats bleiben getrennt.", en = "Forever Chat: it takes in every chat source, including say, yell, emotes, Battle.net whispers and community channels. Whispers and Battle.net chats stay separate." },
        { de = "Forever Chat: Chats werden nur auf diesem PC gespeichert und kommen nach einem Neuladen oder Neustart zurück. Du kannst das Speichern ausschalten und den Verlauf jederzeit löschen.", en = "Forever Chat: chats are saved on this PC only and come back after a reload or a restart. You can switch saving off and delete the history at any time." },
        { de = "Forever Chat: Öffnet sich von selbst je Art des Chats (standardmäßig aus). Nutze eine Tastenbelegung, /fg chat, /fgchat, einen optionalen Bildschirm-Knopf oder das Minimap-Symbol mit der Ungelesen-Zahl.", en = "Forever Chat: opens by itself per kind of chat (off by default). Use a key binding, /fg chat, /fgchat, an optional screen button or the minimap icon with the unread count." },
        { de = "Forever Chat: Ein kleines Fenster je Flüster-Partner, ein Knopf Neue Nachricht (Strg+N), ein Entwurf je Chat und eine Einstellungskarte für Darstellung, Zeitstempel, Schlüsselwörter, Erwähnungen, Ton und Deckkraft.", en = "Forever Chat: a small window per whisper partner, a New message button (Ctrl+N), a draft per chat and a settings card for view, time stamps, keywords, mentions, sound and opacity." },
        { de = "Teams: Eigene Chats mit anderen Addon-Nutzern, bis 80 Mitglieder. Eine Einladung muss angenommen werden, jedes Team hat ein Symbol und einen Verlauf. Teams funktionieren nur mit eingeschaltetem Teilen.", en = "Teams: your own chats with other add-on users, up to 80 members. An invite has to be accepted, every team has an icon and a history. Teams only work with sharing switched on." },
        { de = "Chat-Logos: Das Forever-Logo, Gilden- und Community-Logos oder neutrale Symbole können an Namen im Chat erscheinen. Standardmäßig aus.", en = "Chat logos: the Forever logo, guild and community logos or neutral symbols can appear at names in chat. Off by default." },
        { de = "Gildenkarte: Gildenmitglieder, die es erlauben, erscheinen auf der Weltkarte und der Minimap. Standardmäßig aus, die Genauigkeit ist einstellbar, Senden und Empfangen sind getrennt.", en = "Guild map: guild members who allow it show on the world map and the minimap. Off by default, the accuracy is adjustable and sending and receiving are separate." },
        { de = "Hersteller-Listen: Wer kann das herstellen? zeigt die Gildenmitglieder, die ein Rezept herstellen, mit Beruf und Skill. Es nutzt geteilte Daten und ist standardmäßig aus. Flüstern bereitet nur Text vor, bis du Enter drückst.", en = "Crafter lists: \"Who can make this?\" shows the guild members who craft a recipe, with profession and skill. It uses shared data and is off by default. Whispers only prepare text until you press Enter." },
        { de = "Einladungen per Flüstern: Wer inv oder ginv flüstert, kann über ein Fenster oder eine Leiste eine Gruppen- oder Gildeneinladung bekommen. Anfragen reihen sich ein, eine Taste bestätigt und die Wartezeit ist einstellbar.", en = "Whisper invites: a player who whispers inv or ginv can get a group or guild invite from a window or a bar. Requests queue up, a key confirms and the waiting time is adjustable." },
        { de = "GildenManager: Zwölf Regelvorlagen, ein Editor und ein Assistent erstellen Regeln, die eine Beförderung, Degradierung, Entfernung, Notiz oder Markierung vorschlagen. Nichts läuft von selbst, du bestätigst jeden Schritt.", en = "GildenManager: twelve rule templates, an editor and an assistant build rules that suggest a promotion, demotion, removal, note or marker. Nothing runs by itself, you confirm every step." },
        { de = "GildenManager: Eine Vorschau zeigt je Mitglied, was passieren würde, mit Trockenlauf, Pausen und Rückgängig. Dazu kommen ein Protokoll mit Export, eine Banliste, eine Übersicht mit Jubiläen und Rückkehrern und Hilfe-Touren.", en = "GildenManager: a preview shows what would happen per member, with dry run, pauses and undo. Added are a log with export, a ban list, an overview with anniversaries and returners, and help tours." },
        { de = "Teilen: Der Reiter Teilen listet jede Funktion mit getrennten Schaltern Senden und Empfangen, alle standardmäßig aus. Ein neuer Einrichtungsschritt führt hindurch. Ohne deine Wahl wird nichts gesendet.", en = "Sharing: the Share tab lists every function with separate Send and Receive switches, all off by default. A new setup step guides you through them. Nothing is sent without your choice." },
        { de = "GildenManager: Beitrittsdaten, Markierungen und Notizen lassen sich mit Offizieren teilen. Standardmäßig aus und nur mit deiner Zustimmung.", en = "GildenManager: join dates, markers and notes can be shared with officers. Off by default and only with your consent." },
      },
      changed = {
        { de = "Versionsnummer: Die Versionen 0.3.0 und 0.4.0 wurden nicht veröffentlicht, deshalb enthält dieses Release alles seit 0.2.0 und springt von 0.2.0 auf 0.5.0.", en = "Version number: Versions 0.3.0 and 0.4.0 were not published, so this release contains everything since 0.2.0 and jumps from 0.2.0 to 0.5.0." },
        { de = "Karte & Route: Filter und Anzeige sind Dropdowns mit Mehrfachauswahl, die eine Kurzfassung zeigen, beim Anklicken offen bleiben und sich mit der Tastatur bedienen lassen.", en = "Map and route: Filters and Display are multi-select dropdowns that show a short summary, keep the list open while you click and work with the keyboard." },
        { de = "Erz- und Kräuterfilter: Sind beide an, zeigen die Addon-Karte und die Weltkarte alle Items jeder Zone auf einmal, und die Auswahl je Zone engt sie ein.", en = "Ore and herb filters: with both checked, the add-on map and the world map show all items of every zone at once, and your selection per zone narrows them down." },
        { de = "Berufsroute: Das Feld Start-Skill steht jetzt vor dem Feld Ziel-Skill.", en = "Profession route: the Start skill field now comes before the Target skill field." },
        { de = "Instanz-Reset: Die Zeile im Gruppenchat ist jetzt standardmäßig aus und wurde beim Update einmalig zurückgesetzt. Schalte sie wieder ein, wenn du sie brauchst.", en = "Instance reset: the group chat line is now off by default and was reset once on update. Switch it on again if you want it." },
        { de = "Einrichtung: Die Zusammenfassung nennt, was du an Teilen eingeschaltet hast, und Alles auf Standard schaltet Teilen ganz aus.", en = "Setup: the summary lists the sharing you switched on, and Reset all switches sharing off completely." },
        { de = "Spieldaten: Talente, Zauber und Lehrerlisten folgen dem aktuellen Forever-Client, die deutschen Namen passen zum Spiel.", en = "Game data: talents, spells and trainer lists follow the latest Forever client build, and the German names match the game." },
      },
      fixed = {
        { de = "Erfahrungsleiste: Die Sitzung zählt jede EP, ein Neuladen oder Teleport verliert keine mehr, und ein neuer Login nach mehr als 10 Minuten Pause startet eine neue Sitzung.", en = "Experience bar: the session counts every XP gain, a reload or teleport no longer loses any, and a new login after a break of more than 10 minutes starts a new session." },
        { de = "Karte & Route: Texte und Knöpfe überdecken sich nicht mehr, auch bei größerer Schrift und kleinem Fenster.", en = "Map and route: texts and buttons no longer overlap, also with a larger font and a small window." },
        { de = "Einrichtungsfenster: Es bleibt über Tutorials und anderen Spielfenstern, und /fg setup close schließt es ohne Maus.", en = "Setup window: it stays on top of tutorials and other game windows, and /fg setup close closes it without the mouse." },
        { de = "Zonenübergänge: Der Pfeil wird mit Linien gezeichnet und zeigt statt der Pfeilform nicht mehr den Buchstaben Z.", en = "Zone transitions: the arrow is drawn with lines and no longer shows a letter Z instead of the arrow shape." },
        { de = "Exporte: Fenster- und Zonenübergang-Zeichenketten verlieren nach einem senkrechten Strich keinen Buchstaben mehr, ältere Zeichenketten werden weiter gelesen. Ein senkrechter Strich im Pin-Text überlebt den JSON-Export.", en = "Exports: window and zone transition strings no longer lose a letter after a pipe character, and older strings are still read. A pipe character in pin text survives the JSON export." },
        { de = "Fensterstil: Das Titelband und die obere Randlinie des Stils WoW Forever sitzen jetzt bündig am Fensterrand.", en = "Window style: the title band and the top border line of the WoW Forever style now sit flush with the window edge." },
      },
    },
  },
}
